<?php $sent=false;$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['_csrf']??null)){$error='Security token expired. Refresh and try again.';}else{$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$stage=trim($_POST['stage']??'');$timeline=trim($_POST['timeline']??'');$message=trim($_POST['message']??'');$subject='Build With Me intake';$details="Stage: {$stage}\nTimeline: {$timeline}\n\n{$message}";if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$message===''){$error='Please provide a valid name, email and project brief.';}else{try{$stmt=db()->prepare('INSERT INTO messages(name,email,subject,message) VALUES(:name,:email,:subject,:message)');$stmt->execute([':name'=>$name,':email'=>$email,':subject'=>$subject,':message'=>$details]);$sent=true;}catch(Throwable $e){$error='The intake service is temporarily unavailable. Please try again later.';}}}} ?><main class="hq-section intake-page"><div class="section-label"><span>09</span><span>Build With Me</span></div><div class="section-heading"><h1 class="dossier-title">Let's make<br><em>something matter.</em></h1><p>Have a hard problem, an early signal, or a future you want to make more legible? Share enough context to start a useful conversation.</p></div><div class="intake-panel"><?php if($sent): ?><p class="intake-success">Message received. I’ll read the brief and respond with the next useful question.</p><?php elseif($error): ?><p class="intake-error"><?=e($error)?></p><?php endif; ?><form method="post" class="contact-form intake-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Your name<input name="name" placeholder="Arshad / team name" required></label><label>Email address<input type="email" name="email" placeholder="you@example.com" required></label><label>Where is the project now?<select name="stage"><option value="Idea">Idea / early signal</option><option value="Prototype">Prototype</option><option value="Live product">Live product</option><option value="Internal system">Internal system</option></select></label><label>What is the horizon?<select name="timeline"><option value="Exploring">Exploring</option><option value="This quarter">This quarter</option><option value="Active now">Active now</option><option value="Longer horizon">Longer horizon</option></select></label><label>Tell me what you are building<textarea name="message" rows="8" placeholder="The problem, the people, and what you want to make possible…" required></textarea></label><button class="hq-button hq-button--primary" type="submit">Send project brief ↗</button></form></div></main>
